from build_engine3 import *

gen=[
step('entry','Confirm engine-bench access','Start with the removed engine securely supported, oil drained, shift pedal removed and stator/position-sensor harness couplers disconnected. Record the two external lead clamps and holder positions before removing the left cover.',[240,241,242],'Oil drained, couplers disconnected, clamps identified.',True,True),
step('cover-remove','Remove the left cover','Release the cover fasteners progressively, remove the external clamps/holder and lift off the left crankcase cover. Retain both dowels and discard the gasket. Preserve the oil-tank drain-bolt washer location.',[240,241,242],'Cover, two dowels and hardware retained.',True,True),
step('stator-remove','Release the stator assembly','Remove the lead clamp/crank-position sensor bolts and three stator screws. Release the lead grommet and remove the assembly without pulling on its wires. Keep the rotor and crankshaft undisturbed until the next step.',[242,243],'Stator, sensor/clamp and grommet retained.',True,True),
step('rotor-remove','Pull the rotor','Hold the rotor at the illustrated wrenching flats while removing its nut and washer. Use rotor puller90890-04151/YM-04151 to remove the rotor. Remove and retain the woodruff key; do not pry against the stator surface.',[243],'Rotor pulled with specified tool; key and washer retained.',True,True),
step('inspect','Inspect contact and key surfaces','Inspect rotor inner surface and stator outer surface for contact damage. Damage requires crankshaft runout and bearing inspection before reassembly. Replace a damaged woodruff key. Record the result; electrical diagnosis is separate.',[243],'Contact-surface and key condition recorded; any crank/bearing fault resolved.',True,True),
step('stator-install','Install stator, sensor and grommet','Refit the stator with its three screws at10Nm using LOCTITE and aT25 bit. Refit crank-position sensor bolts at10Nm using LOCTITE. Apply YamahaBond1215/ThreeBond1215 to the lead grommet and route the lead through the cover side exactly as illustrated.',[240,243],'Stator/sensor10Nm, locking agent and1215 grommet seal recorded.',True,True),
step('rotor-install','Install the keyed rotor','Clean both tapered mating surfaces. Fit the woodruff key with its flat face parallel to the crankshaft centerline. Align the rotor keyway with the key, seat the rotor, install washer/nut and hold the illustrated flats while tightening to65Nm.',[244],'Key alignment, clean taper and65Nm saved.',True,True),
step('cover-install','Close the left side','Fit both dowels and a new left-cover gasket. Return the cover, lead clamps and holder to their diagram locations. Tighten cover bolts progressively in a crisscross pattern to10Nm. Fit a new oil-tank drain washer and tighten that drain bolt10Nm. Leave harness reconnection for engine installation with the routing guide.',[242,244],'New gasket/washer, dowels and all10Nm closures checked.',True,True)]
procedure('generator-bench-v1','Remove and refit the engine generator',gen,['Engine removed, oil drained, shift pedal removed and electrical couplers disconnected.'],['Generator and left cover installed; harness remains disconnected for engine refit.'],['Rotor puller90890-04151/YM-04151','Suitable holder/wrench for rotor flats','T25 bit; torque wrench accurate at10/65Nm'],['New left-cover gasket and oil-tank drain washer','YamahaBond1215/ThreeBond1215','LOCTITE locking agent; grade unspecified'],['Electrical coil diagnosis','Engine removal and harness routing closure'],['engine','generator'])

case=[
step('entry','Confirm complete case-opening access','Engine is out and drained. Piston/cylinder, oil pump, shift segment, generator/stator, clutch-release unit/pushrod2 and external crank/balancer gear stacks must already be removed. Record that each access operation is actually complete before opening cases.',[276,277,283],'All named opening prerequisites confirmed.',True,True),
step('chain','Remove lower timing-chain parts','Remove exhaust-side chain guide and stopper plate, then lift away the timing chain. Retain each part by location and keep the crankcase opening clean.',[276],'Guide, plate and chain retained.',True,True),
step('bolts','Release the case fasteners','Map all nine case bolts to the source drawing: three45mm, three60mm and three75mm bolts. Loosen every bolt one quarter-turn at a time in successive passes until loose, then remove them.',[276,280],'Nine bolts removed; lengths and positions logged.',True,True),
step('split','Separate the right case horizontally','Support the engine with the left crankcase down. Separate the right case horizontally so crankshaft and transmission remain in the left half. Insert only the screwdriver tip at the illustrated splitting slit; light soft-hammer taps may be made only on the indicated slit/mount bosses. Do not strike mating faces or force a case still held by a bolt or fitting.',[280],'Right case separated with mating faces undamaged.',True,True),
step('internals-out','Complete the internal removal operations','Retain the two case dowels and O-ring. Complete the transmission removal and crankshaft/balancer removal operations before case bearing work. Preserve the oil-strainer and oil-nozzle positions in the two case halves.',[277,280,283,284],'Cases empty of shafts; dowels/O-ring and oil components accounted for.',True,True),
step('clean','Clean and inspect the case halves','Remove residual gasket material without damaging the sealing faces; clean the cases with mild solvent. Clear oil passages with compressed air. Replace cracked/damaged cases. Inspect the timing chain for stiffness and guides for wear; chain faults require the specified chain and sprocket set replacement, not an isolated reused damaged sprocket.',[280],'Case faces, oil passages, chain and guide assessment recorded.'),
step('strainer','Inspect the strainer and nozzles','Inspect the oil strainer for damage and replace if damaged; wash contamination away with solvent. Keep the two different oil nozzles identified by their respective left/right locations. Account for the small oil-passage gasket so it cannot be omitted at closure.',[277,281],'Strainer clean/intact; nozzle and gasket positions recorded.',True,True),
step('bearings','Replace required case bearings correctly','For a bearing requiring replacement, remove its retainer and press out against the inner race; the removed bearing is discarded. Press the new bearing parallel by its outer race only, fully to the0mm seated positions in the left/right exploded diagrams. Oil the new bearings. Match each original bearing to its exact bore and retainer.',[278,279,280],'Replaced bearing locations and fully seated positions saved.',True,True),
step('retainers','Install case retainers and new seal','Refit bearing retainers with LOCTITE: ordinary retainer bolts12Nm, crankshaft-bearing retainer bolts30Nm, exactly at the diagram locations. Fit a new left-case oil seal parallel at0–0.5mm illustrated depth and grease its lip with lithium-soap grease.',[278,279,281],'Every retainer classified and torqued; new seal depth saved.',True,True),
step('internals-in','Install and verify the internal assemblies','Complete crankshaft/balancer installation and transmission installation into the left case. Record their measured inspection results and smooth transmission operation before closing the case. Keep the connecting rod atTDC for case assembly.',[281,283,285,292],'Crank and transmission operations complete; rod atTDC.',True,True),
step('oil-parts','Restore the case oil components','Install oil nozzle1 in the right case with its bolt10Nm and LOCTITE. Install oil nozzle2 in the left case at0.5Nm. Refit the strainer, its new O-ring with lithium-soap grease, both dowels and the new illustrated small gasket. Use the exact left/right exploded views.',[277,281],'Nozzles10Nm/0.5Nm; strainer O-ring, dowels and small gasket verified.',True,True),
step('seal','Seal and join the halves','Apply YamahaBond1215/ThreeBond1215 to the mating-face path shown in the source diagram. Keep passages unobstructed. With the rod held atTDC, lower the right case onto the left case horizontally, matching shafts and dowels without force.',[281,282],'Specified sealant and path; rodTDC; cases seated.',True,True),
step('case-torque','Tighten the matched case bolts','Install all nine bolts at their documented length positions. Tighten in a crisscross pattern in two stages, advancing bolts by one quarter-turn per pass, to12Nm. Check shaft rotation and transmission movement before proceeding to peripheral reassembly; binding must be corrected, not pulled through with bolt torque.',[282,292],'Nine positions and12Nm recorded; free movement verified.',True,True)]
procedure('crankcase-bench-v1','Open, inspect and close the crankcases',case,['Removed/drained engine with top end and named external assemblies removed.','Transmission/crankshaft removal and installation modules available.'],['Crankcases closed around inspected crank/transmission; external assemblies and top end remain off.'],['Soft hammer, appropriate case support, circlip tools','Bearing press and parallel drivers contacting specified races','Low-range torque tools accurate at0.5/10/12/30Nm'],['New case oil seal, oil-strainer O-ring and small oil-passage gasket','New exact bearings as required; never reuse a pressed-out bearing','Engine oil, lithium-soap grease, LOCTITE','YamahaBond1215/ThreeBond1215'],['Automatic certification of dependent crank/transmission work','Engine access/closure outside case boundary'],['engine','crankcase','transmission'])

crank=[
step('entry','Confirm crankshaft access','Start with the cases separated, transmission removed and the crankshaft/balancer retained in the left case. Ensure the external balancer and primary gears have been removed before attempting shaft removal.',[283,284],'Left-case crankshaft entry state confirmed.',True,True),
step('balancer-out','Remove the balancer shaft','Turn the balancer so its flat face points toward the crankshaft, as shown, then remove it. Keep its contact surfaces protected.',[284],'Balancer orientation and removal recorded.',True,True),
step('crank-out','Remove the crankshaft assembly','Use crankcase separator90890-04152/YU-A9642 mounted at the illustrated left-case holes to press the crankshaft out. Keep the crankshaft supported and protect the mating face; do not substitute uncontrolled hammer blows.',[284],'Specified separator used; crank removed intact.',True,True),
step('runout','Measure crankshaft runout','Support the crankshaft as illustrated and rotate it slowly while reading the dial indicator at the indicated journal. Limit0.030mm. Record the measured result and replace an out-of-limit complete assembly.',[284],'Crankshaft runout in mm saved.',True,True),
step('width','Measure width and inspect the sprocket','Measure crank assembly width between the shown faces:61.93–62.00mm. Inspect the crank sprocket for damage/wear; replace the crankshaft assembly if defective. Clear an obstructed journal oil passage with compressed air and recheck it.',[284],'Width, sprocket condition and open oil passage recorded.',True,True),
step('install','Draw the complete crankshaft into the left case','Grease the oil-seal lip with lithium-soap grease and apply molybdenum-disulfide grease to the illustrated crankshaft location. Use installer pot90890-01274/YU-90058, bolt90890-01275/YU-90060, M12 adapter90890-01278/YU-90063 and spacer90890-04081/YM-91044. Hold the rod atTDC while turning the installer until the crank bottoms against the bearing.',[285],'Correct installer parts, rodTDC and crank seating recorded.',True,True),
step('balancer-in','Return the balancer and hand off','Install the balancer in the left case in the reverse physical orientation of removal with its flat toward the crankshaft to pass the crank. Check free movement and retain the rodTDC position for subsequent case closure. Balancer gear timing is performed separately when the external gears return.',[283,284,285],'Crank/balancer seated; free movement recorded.',True,True)]
procedure('crankshaft-assembly-bench-v1','Inspect and replace the crankshaft assembly',crank,['Cases split; transmission and external crank/balancer gear stacks removed.'],['Inspected complete crankshaft and balancer installed in left case; transmission and case closure still required.'],['Crankcase separator90890-04152/YU-A9642','Crank installer pot90890-01274/YU-90058, bolt90890-01275/YU-90060, M12 adapter90890-01278/YU-90063, spacer90890-04081/YM-91044','Crank supports, dial indicator, precision width measuring tool'],['Exact complete crankshaft assembly if required','Lithium-soap grease and molybdenum-disulfide grease'],['Connecting-rod pin pressing, crank truing or crank assembly fabrication; OEM gives no press dimensions here','Complete engine closure'],['engine','crankshaft'])
manifest()
